import json
from pathlib import Path
from html import escape as e
root = Path(__file__).parent
data = json.loads((root/'common-content.json').read_text(encoding='utf-8-sig'))
paths = {
'file':'<path d="M6 3h9l6 6v16H6zM15 3v7h6M10 15h7M10 20h7"/>',
'link':'<path d="M11 17 7 21H2v-7l7-7h6v5M17 11l4-4h5v7l-7 7h-6v-5M9 19l10-10"/>',
'folder':'<path d="M3 7h9l3 4h10v14H3zM3 12h22M10 18h9m-4-4 4 4-4 4"/>',
'clipboard':'<path d="M6 6h4V3h8v3h4v19H6zM10 6v3h8V6M10 15h8M10 20h8"/>',
'search':'<path d="M3 3h15v15H3zM18 18l8 8"/>',
'mic':'<path d="M10 3h8v14h-8zM6 12v9h16v-9M14 21v5M9 26h10"/>'}
def svg(key, cls=''):
    return f'<svg class="{cls}" viewBox="0 0 28 28" aria-hidden="true">{paths[key]}</svg>'
def row(t, native):
    fail=t['state']=='failed'; running=t['state']=='running'
    english=f'<span class="english">{e(t["englishName"])}</span>' if t.get('englishName') else ''
    desc=f'<span class="error-text" id="everything-error">{e(t["error"])}</span>' if fail else e(t['description'])
    checked='true' if running else 'false'
    disabled=' disabled aria-disabled="true" aria-describedby="everything-error"' if fail else ''
    label=f'{t["name"]}启停' + ('，启动失败，请先修复路径' if fail else '')
    link='<button type="button" class="text-action repair">修复路径</button>' if fail else f'<button type="button" class="text-action" aria-label="{e(t["name"])}设置">设置</button>'
    return f'''<article class="tool {t['state']}"><div class="tool-icon {'native' if native else ''}">{svg(t['glyph'])}</div><div class="tool-copy"><div class="tool-title">{e(t['name'])}{english}</div><div class="description">{desc}</div></div><div class="status"><i aria-hidden="true"></i>{e(t['stateText'])}</div><div class="row-actions"><button type="button" class="switch" role="switch" aria-checked="{checked}" aria-label="{e(label)}"{disabled}><span class="thumb"></span></button>{link}</div></article>'''
sections=[]
for i,g in enumerate(data['groups']):
    add='<button type="button" class="add-program"><span aria-hidden="true">+</span> 添加程序</button>' if i else ''
    sections.append(f'<section class="section"><div class="group-title"><h2>{e(g)}<span class="count">3</span></h2>{add}</div>'+''.join(row(t,i==0) for t in data['tools'][i*3:i*3+3])+'</section>')
css='''
*{box-sizing:border-box;border-radius:0!important}html,body{margin:0;min-height:100vh}body{display:grid;place-items:center;background:#ECEDEB;color:#20231F;font-family:"Microsoft YaHei","Microsoft YaHei UI",sans-serif;font-size:14px;-webkit-font-smoothing:antialiased}button{font:inherit;color:inherit;cursor:default}button:focus-visible{outline:2px solid #C45325;outline-offset:3px}svg{fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:square;stroke-linejoin:miter;display:block}.app-window{width:980px;height:700px;display:grid;grid-template-rows:40px 616px 42px;border:1px solid #20231F;background:#F4F1E8;overflow:hidden}.titlebar{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #20231F;padding-left:18px;font-size:13px}.app-title{display:flex;align-items:center;gap:9px}.title-mark{width:13px;height:13px;background:#C45325;position:relative}.title-mark:after{content:"";position:absolute;background:#20231F;width:5px;height:5px;right:0;bottom:0}.window-actions{height:39px;display:flex}.window-actions button{width:44px;border:0;border-left:1px solid #D5D3C9;background:transparent;display:grid;place-items:center}.window-actions svg{width:12px;height:12px;stroke-width:1}.body{display:grid;grid-template-columns:180px 1fr;min-height:0}.sidebar{background:#EAE6DB;border-right:1px solid #20231F;display:flex;flex-direction:column;padding:16px 13px 13px}.character{height:177px;display:grid;place-items:center;margin-bottom:17px;position:relative}.character:before{content:"";width:49px;height:6px;background:#C45325;position:absolute;left:0;bottom:0}.character img{display:block;width:142px;height:160px;object-fit:contain;position:relative;align-self:start}.nav{width:100%;height:42px;border:1px solid transparent;background:transparent;text-align:left;padding:0 12px;display:flex;align-items:center;gap:11px;margin-bottom:6px;color:#5D6158}.nav svg{width:18px;height:18px}.nav.selected{background:#20231F;color:#F4F1E8;border-color:#20231F;font-weight:600}.nav.selected:after{content:"";height:7px;width:7px;margin-left:auto;background:#D0F15C}.nav-bottom{margin-top:auto;border-top:1px solid #C5C4BA;padding-top:12px}.main{padding:25px 26px 0;min-width:0}.page-head{display:flex;align-items:flex-start;justify-content:space-between;height:72px}.page-head h1{font-size:24px;line-height:32px;font-weight:700;letter-spacing:-.8px;margin:0;display:flex;align-items:center;gap:12px}.page-head h1:before{content:"";display:block;width:7px;height:26px;background:#C45325}.bulk-actions{display:flex;gap:8px}.bulk-actions button{height:34px;padding:0 14px;background:transparent;border:1px solid #20231F;font-size:13px;font-weight:600}.bulk-actions .primary{background:#B64820;border-color:#B64820;color:#FFF9ED}.group-title{height:31px;border-bottom:2px solid #20231F;display:flex;justify-content:space-between;align-items:flex-start}.group-title h2{font-size:13px;font-weight:700;line-height:21px;margin:0}.count{margin-left:10px;color:#686B61;font-family:Bahnschrift,"Microsoft YaHei",sans-serif;font-size:13px;font-weight:400}.add-program{border:0;background:transparent;color:#99411F;font-size:13px;line-height:21px;padding:0}.add-program span{font-size:18px}.tool{height:69px;border-bottom:1px solid #D6D4CA;display:grid;grid-template-columns:30px minmax(0,1fr) 77px 120px;gap:12px;align-items:center}.tool:last-child{border-bottom:0}.tool-icon{color:#55594F;width:27px;height:27px}.tool-icon.native{color:#C45325}.tool-icon svg{width:27px;height:27px}.tool-title{font-size:16px;line-height:23px;font-weight:700;white-space:nowrap}.english{font-family:Bahnschrift,"Microsoft YaHei",sans-serif;margin-left:9px;font-size:13px;color:#686B61;font-weight:400}.description{font-size:13px;line-height:22px;color:#686B61;white-space:nowrap}.status{font-size:13px;white-space:nowrap;display:flex;gap:7px;align-items:center;color:#686B61}.status i{display:block;width:6px;height:6px;background:#9B9D92}.running .status{color:#20231F}.running .status i{background:#20231F}.failed .status{color:#A4411D}.failed .status i{background:#C45325}.error-text{color:#A4411D}.row-actions{display:flex;align-items:center;justify-content:space-between;gap:10px}.switch{width:48px;height:24px;flex:0 0 48px;padding:3px;border:1px solid #A1A398;background:#D9DACF;position:relative}.switch .thumb{position:absolute;left:3px;top:3px;width:16px;height:16px;background:#F4F1E8;border:1px solid #777C6E}.switch[aria-checked=true]{background:#20231F;border-color:#20231F}.switch[aria-checked=true] .thumb{left:27px;border-color:#F4F1E8;background:#F4F1E8}.switch:disabled{border-color:#CFA18C;background:repeating-linear-gradient(135deg,#EFE0D3 0px,#EFE0D3 4px,#E4C9B7 4px,#E4C9B7 5px);opacity:1}.switch:disabled .thumb{border-color:#B9856B;background:#E8D9C9}.text-action{border:0;background:transparent;padding:0;color:#686B61;font-size:13px;white-space:nowrap}.text-action.repair{color:#A4411D;text-decoration:underline;text-underline-offset:4px}.section+.section{margin-top:19px}.footer{display:flex;align-items:center;border-top:1px solid #20231F;font-size:13px;color:#666A5F;padding:0 26px 0 206px}.footer-note{display:flex;gap:8px;align-items:center}.footer-note svg{width:14px;height:14px;stroke-width:1.3}
'''
html='''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=980,initial-scale=1"><title>Eous 助手 · 抽象构成</title><style>'''+css+'''</style></head><body><div class="app-window"><header class="titlebar"><div class="app-title"><span class="title-mark" aria-hidden="true"></span>Eous 助手</div><div class="window-actions"><button type="button" aria-label="最小化"><svg viewBox="0 0 12 12"><path d="M1 6h10"/></svg></button><button type="button" aria-label="最大化"><svg viewBox="0 0 12 12"><path d="M1.5 1.5h9v9h-9z"/></svg></button><button type="button" aria-label="关闭面板"><svg viewBox="0 0 12 12"><path d="m2 2 8 8m0-8-8 8"/></svg></button></div></header><div class="body"><aside class="sidebar"><div class="character"><img src="assets/eous-abstract.png" alt="几何抽象风格 Eous：奶白兔耳头罩、荧绿双眼和橙色围巾"></div><nav><button type="button" class="nav selected" aria-current="page"><svg viewBox="0 0 20 20"><path d="M2 2h6v6H2zM12 2h6v6h-6zM2 12h6v6H2zM12 12h6v6h-6z"/></svg>工具总览</button></nav><div class="nav-bottom"><button type="button" class="nav"><svg viewBox="0 0 20 20"><path d="M8 2h4v3l3 2 3-1 1 4-3 2v3l-4 3-3-2-3 1-3-4 2-3-1-3 4-2zM8 8h4v4H8z"/></svg>设置</button><button type="button" class="nav"><svg viewBox="0 0 20 20"><path d="M2 2h16v16H2zM10 8v6M10 5v.5"/></svg>关于 Eous</button></div></aside><main class="main"><div class="page-head"><h1>工具总览</h1><div class="bulk-actions"><button type="button" class="primary">全部启动</button><button type="button">全部关闭</button></div></div>'''+''.join(sections)+'''</main></div><footer class="footer"><div class="footer-note"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M1.5 1.5h13v13h-13zM8 7v4M8 4v.5"/></svg>'''+e(data['footer'])+'''</div></footer></div></body></html>'''
(root/'abstract.html').write_text(html,encoding='utf-8')
print('Created abstract.html from common-content.json; 6 tools; all UI radius 0.')
